package dev.gravaai.services.agent;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

import dev.gravaai.core.json.Json;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ArrayNode;
import tools.jackson.databind.node.ObjectNode;

/**
 * The MCP tool surface (port of {@code electron/agent/toolSchemas.ts}, plan §5.16). The data lives
 * in {@code agent/tool-schemas.json}, generated byte-identically from the TypeScript constants by
 * {@code AgentToolSchemasMatchTsTest} (like {@code PromptsMatchTsTest}).
 */
public final class AgentToolSchemas {

	/** One MCP tool definition ({@code AgentToolDefinition}). */
	public record ToolDefinition(String name, String description, String inputSchemaJson) {}

	private static final String RESOURCE = "/agent/tool-schemas.json";

	private static final String INSTRUCTIONS;
	private static final List<ToolDefinition> TOOLS;
	private static final String TOOLS_JSON;

	static {
		try (InputStream stream = AgentToolSchemas.class.getResourceAsStream(RESOURCE)) {
			if (stream == null) {
				throw new IllegalStateException("missing resource " + RESOURCE);
			}
			JsonNode root = Json.parseJsonWithByteOrderMark(
					new String(stream.readAllBytes(), StandardCharsets.UTF_8));
			INSTRUCTIONS = root.path("instructions").asText("");
			ArrayNode tools = (ArrayNode) root.path("tools");
			List<ToolDefinition> definitions = new ArrayList<>();
			for (JsonNode tool : tools) {
				String schemaJson = Json.MAPPER.writeValueAsString(tool.path("inputSchema"));
				definitions.add(new ToolDefinition(tool.path("name").asText(""),
						tool.path("description").asText(""), schemaJson));
			}
			TOOLS = List.copyOf(definitions);
			TOOLS_JSON = Json.MAPPER.writeValueAsString(tools);
		} catch (IOException error) {
			throw new IllegalStateException("could not load " + RESOURCE, error);
		}
	}

	private AgentToolSchemas() {}

	/** {@code AGENT_INSTRUCTIONS}. */
	public static String instructions() {
		return INSTRUCTIONS;
	}

	/** {@code AGENT_TOOLS}. */
	public static List<ToolDefinition> tools() {
		return TOOLS;
	}

	/** {@code findAgentTool}. */
	public static Optional<ToolDefinition> find(String name) {
		return TOOLS.stream().filter(tool -> tool.name().equals(name)).findFirst();
	}

	/** {@code toolListTokenEstimate}: approximate cost of the tool list (4 chars per token). */
	public static int toolListTokenEstimate() {
		return (int) Math.ceil(TOOLS_JSON.length() / 4.0);
	}

	/** The compact JSON of the tools array as the TypeScript constants serialise it. */
	public static String toolsJson() {
		return TOOLS_JSON;
	}

	/** The raw resource bytes (the exact JSON the constants serialise to). */
	public static String rawResource() {
		try (InputStream stream = AgentToolSchemas.class.getResourceAsStream(RESOURCE)) {
			return new String(stream.readAllBytes(), StandardCharsets.UTF_8);
		} catch (IOException error) {
			throw new IllegalStateException("could not read " + RESOURCE, error);
		}
	}

	/** Helper for tests: the schema object of one tool. */
	public static ObjectNode schemaOf(String name) {
		return (ObjectNode) Json.MAPPER.readTree(find(name)
				.orElseThrow(() -> new IllegalArgumentException("unknown agent tool: " + name))
				.inputSchemaJson());
	}
}
